import { useInventory } from "../../context/InventoryContext";

export default function Inventory() {
  const { inventory } = useInventory();

  const groupByCollege = items => {
    return items.reduce((acc, item) => {
      const college = item.college || "Unknown";
      if (!acc[college]) acc[college] = [];
      acc[college].push(item);
      return acc;
    }, {});
  };

  const groupedInventory = groupByCollege(inventory);

  return (
    <div className="admin-section">
      <h3>Inventory</h3>

      {inventory.length === 0 && <p>No inventory data</p>}

      {Object.entries(groupedInventory).map(([college, items]) => (
        <div key={college} style={{ marginBottom: "30px" }}>
          <h4
            style={{
              margin: "16px 0 8px",
              color: "#1e40af",
              borderBottom: "1px solid #ddd",
              paddingBottom: "4px"
            }}
          >
            {college}
          </h4>

          {items.map(item => (
            <div key={item.id} className="inventory-row">
              <strong>{item.name}</strong>
              <span>₹{item.price}</span>
              <span>Stock: {item.stock}</span>
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}
